('capacity.unassigned_summary.warn_threshold_hours', 'Capacity: Unassigned Hours Warn Threshold', 'Hours/period at or above which the project-view unassigned-summary cell shows amber (below this value the cell is empty)', '1', '1', 'integer', 'thresholds', '2026-01-15 10:00:00', '2026-01-15 10:00:00'),
('capacity.unassigned_summary.danger_threshold_hours', 'Capacity: Unassigned Hours Danger Threshold', 'Hours/period at or above which the project-view unassigned-summary cell shows red instead of amber', '200', '200', 'integer', 'thresholds', '2026-01-15 10:00:00', '2026-01-15 10:00:00'),
INSERT INTO kpi_definitions (name, description, formula, display_format, target_value, is_built_in, is_active, created_at) VALUES
('Total Baseline', 'Sum of all project baselines', 'SUM(baseline.amount_eur)', 'currency', NULL, 1, 1, '2026-01-15 10:00:00'),
('Current Forecast', 'Sum of all project forecasts', 'SUM(forecast.amount_eur)', 'currency', NULL, 1, 1, '2026-01-15 10:00:00'),
('YTD Actuals', 'Year-to-date recorded costs', 'SUM(actuals.amount_eur) WHERE year=current', 'currency', NULL, 1, 1, '2026-01-15 10:00:00'),
('Plan Drift', 'Forecast minus Baseline', 'forecast_total - baseline_total', 'currency', '0', 1, 1, '2026-01-15 10:00:00'),
('Portfolio Utilization', 'Average resource utilization', 'AVG(person_utilization_pct)', 'percentage', '85', 1, 1, '2026-01-15 10:00:00'),
('Run/Change Ratio', 'Services vs Projects budget split', 'services_budget / projects_budget', 'ratio', NULL, 1, 1, '2026-01-15 10:00:00'),
('CapEx/OpEx Ratio', 'Capital vs Operating expenditure split', 'capex_total / opex_total', 'ratio', NULL, 1, 1, '2026-01-15 10:00:00');
