(1, 'proj-erp2', 'p-sharma', '2025-06-15 09:30:00', 'approved', 'resource', 'Increase Sr Developer MUC hours to address integration backlog', 'Integration testing revealed more complex data mappings than anticipated.', 0, 'p-brenner', '2025-06-16 11:00:00', 'confirmed', NULL, 'p-meier', '2025-06-17 14:00:00', 'approved', NULL, NULL, '2025-06-15 09:30:00'),
(2, 'proj-erp2', 'p-sharma', '2025-06-20 10:00:00', 'approved', 'external_cost', 'Increase Deloitte consulting budget for extended SAP support', 'Deloitte advisory scope expanded to cover additional module integrations.', 0, 'p-brenner', '2025-06-21 09:00:00', 'confirmed', NULL, 'p-meier', '2025-06-22 16:00:00', 'approved', NULL, NULL, '2025-06-20 10:00:00'),
(9, 'proj-erp2', 'p-sharma', '2026-03-05 09:00:00', 'pending_cc_confirmation', 'resource', 'Increase Sr Developer MUC hours Apr-Jun 2026 + extend Deloitte consulting through Q3', 'Final sprint for go-live requires additional senior capacity and continued advisory support.', 0, 'p-brenner', NULL, 'pending', NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-05 09:00:00'),
(15, 'proj-sensor', 'p-sharma', '2026-03-08 09:30:00', 'pending_cc_confirmation', 'external_cost', 'Add AWS infrastructure scaling costs for production rollout', 'Production deployment requires additional infrastructure capacity beyond development estimates.', 0, 'p-brenner', NULL, 'pending', NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-08 09:30:00'),
(19, 'proj-iam-run', 'p-brenner', '2026-03-03 10:00:00', 'pending_controller_approval', 'external_cost', 'Licensing cost increase + additional security consultant for migration complexity', 'Vendor licensing model change and additional complexity discovered during implementation require budget adjustment.', 0, 'p-brenner', '2026-03-04 11:00:00', 'confirmed', NULL, 'p-meier', NULL, 'pending', NULL, NULL, '2026-03-03 10:00:00'),
(27, 'proj-predmaint', 'p-sharma', '2026-02-20 10:00:00', 'sent_back_by_controller', 'timeline', 'Extend project end date by 3 months for production pilot', 'PoC results justify production pilot but require additional time and resources.', 0, 'p-brenner', '2026-02-21 11:00:00', 'confirmed', NULL, 'p-meier', '2026-02-25 14:00:00', 'sent_back', 'Timeline extension needs more justification. Please provide a detailed milestone plan for the production pilot phase and demonstrate how the additional 3 months maps to specific deliverables.', 'The 3-month extension is reasonable but the resource increase is too high. I have reduced Sr Developer hours from 60 to 50 hrs/mo for the extended period and capped the ML Platform License at 3500 EUR/mo instead of 4000.', '2026-02-20 10:00:00'),
(28, 'proj-mdh-rollout', 'p-sharma', '2026-03-07 09:00:00', 'approved', 'resource', 'Add Data Engineer BUD for Build phase parallelism', 'Build phase scope expanded with additional source-system integrations.', 0, 'p-brenner', '2026-03-08 10:00:00', 'confirmed', NULL, 'p-meier', '2026-03-10 11:00:00', 'approved', NULL, NULL, '2026-03-07 09:00:00');
