(3, 'change_request', 'Change Request', 'PL drafts CR -> CC owner confirmation -> Controller approval -> Apply to baseline.', 1, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
(4, 'send_back', 'Send Back', 'Controller marks send-back, PL revises, request is re-routed into the originating workflow.', 1, '2026-01-01 00:00:00', '2026-01-01 00:00:00');
