(9, 2, 4, 'Controller approval to advance to DoI 2', 'Controller approves; project advances to DoI 2 (Under Evaluation).', 'gate', 1, 0, 'controller', '["complexity_scores", "value_creation_scores"]', '{"on_completion": ["pl"]}', 21, 'escalate_to_manager'),
