(11, 3, 2, 'CC owner confirmation', 'CC owner confirms or declines the resource impact for the CR.', 'review', 1, 0, 'cost_center_owner', NULL, '{"on_start": ["cc_owner"]}', 5, 'reminder'),
(12, 3, 3, 'Controller approval', 'Controller approves, rejects, or sends back the CR.', 'review', 1, 0, 'controller', NULL, NULL, 7, 'escalate_to_manager'),
(13, 3, 4, 'Apply to baseline', 'On approval, forecast lines are updated and a forecast_version is snapshotted.', 'action', 1, 0, 'controller', NULL, '{"on_completion": ["pl", "cc_owner"]}', NULL, NULL),
(14, 4, 1, 'Controller marks send-back', 'Controller annotates the submission and routes it back to the PL.', 'action', 1, 0, 'controller', '["change_notes"]', '{"on_start": ["pl"]}', NULL, NULL),
