INSERT INTO system_suggestions (project_id, suggestion_type, observation, recommendation, impact_description, pre_filled_changes_json, created_at) VALUES
('proj-erp2', 'trend_based', 'Consulting costs have exceeded forecast by 15-20% for the past 6 months. The trend suggests continued overrun through project end.', 'Consider renegotiating the Deloitte advisory scope or capping monthly consulting spend at current forecast levels.', 'Potential savings of EUR 18,000-25,000 over remaining project months if consulting costs are capped.', '{"changes": [{"type": "external", "line": "SAP Implementation Support", "action": "cap_at_forecast"}]}', '2026-04-01 08:00:00'),
('proj-sensor', 'burn_rate', 'External costs (consulting + cloud) are running 25% above baseline. At current burn rate, the project will exceed its approved budget by EUR 45,000.', 'Submit a change request to formally adjust the external cost forecast, or identify areas where internal effort can replace external consulting.', 'Without intervention, projected budget overrun of EUR 45,000 by project end (December 2026).', '{"changes": [{"type": "external", "line": "Data Engineering Consulting", "action": "reduce_by_pct", "pct": 15}]}', '2026-04-01 08:00:00'),
('proj-iam-run', 'actuals_correction', 'ServiceNow licensing costs increased 40% after vendor pricing change. Current run-cost forecast may not fully reflect the compounding impact.', 'Review forecast for ServiceNow ITSM Licenses line item and ensure all remaining months reflect the updated pricing.', 'Forecast accuracy improvement: ensures remaining 6 months correctly reflect EUR 5,600/month vs potential underestimate.', '{"changes": [{"type": "external", "line": "ServiceNow ITSM Licenses", "action": "update_forecast", "amount": 5600}]}', '2026-04-01 08:00:00'),
('proj-mdh-rollout', 'utilization', 'Master Data Hub steady-state operation will require dedicated data-steward capacity by Q3 2026. Current allocation does not reflect this transition.', 'Add 0.5 FTE Data Steward (role-data-eng) starting July 2026, ramping to 1.0 FTE by October 2026 as the offering goes live.', 'Without this capacity, expect ~3-week MDH change-request lead times; with it, lead time stays under 1 week.', '{"changes": [{"type": "internal", "role": "role-data-eng", "action": "increase_hours", "delta": 80, "from_month": "2026-07"}]}', '2026-04-05 09:00:00');
